		 *                    info_slot = 0x100 */
		for (p = 0; p < 2; ++p)
		  if (count_who & (p == tp ? ASTERISK_COUNT_CONTROLLER : ASTERISK_COUNT_OPPONENT))
			for (c = 0; c < 500; ++c)
			  {
				int iid = get_grave(p)[c];
