						}
						if( found == 1 ){
							SET_BYTE1(result) |= to_report;
						}
						if( found == 2 ){
							SET_BYTE2(result) |= to_report;
						}
						if( found == 3 ){
							SET_BYTE3(result) |= to_report;
						}
					}
					found++;
					if( found == max_test_to_get ){
						break;
					}
				}
				count++;
				if( count == max_cards_to_reveal ){
					break;
				}
