	// pow / tou = 0 --> Don't set any new P/T, use the one already present on the card (Vehicles)
	// pow / tou = -1 --> P/T equal to CMC of the "animated" permanent

	int legacy = -1;
	if( t_player != -1 && t_card != -1 ){
