  int effect_fn = instance->targets[2].player;
  int counter_type = BYTE3(mode);

  if (event == EVENT_CHANGE_TYPE && affect_me(t_player, t_card)
	  && iid != -1 && !(land_can_be_played & LCBP_DURING_EVENT_CHANGE_TYPE_SECOND_PASS))
